/* 长按菜名：复制菜名（手机上选不中文字，给个快捷方式） */
function bindLongPressName(sheet, r) {
  var nameEl = $('.sh-name', sheet);
  if (!nameEl) return;
  var holdTimer = 0;
  function cancelHold() {
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = 0; }
  }
  nameEl.addEventListener('pointerdown', function () {
    cancelHold();
    holdTimer = setTimeout(function () {
      holdTimer = 0;
      copyText(r.name);
    }, 550);
  });
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(function (ev) {
    nameEl.addEventListener(ev, cancelHold);
  });
}

